{
  "conversation_lines": [
    {
      "turn_number": 1,
      "time": "2155-04-27 20:15:00",
      "speaker": "Doctor",
      "text": "Hi, I’m Dr. Lee. I’ll be looking after you tonight. I see you came in with worsening abdominal pain and nausea since your last discharge. Can you tell me more about how you’ve been feeling?"
    },
    {
      "turn_number": 2,
      "time": "2155-04-27 20:16:30",
      "speaker": "Patient",
      "text": "Yes, thank you. The pain came back about three days ago—same spot, upper middle abdomen. It’s sharp and gets worse after eating. I haven’t been able to keep food down for two days."
    },
    {
      "turn_number": 3,
      "time": "2155-04-27 20:18:00",
      "speaker": "Doctor",
      "text": "I see. And your last bowel movement was today—was it normal in color and consistency?"
    },
    {
      "turn_number": 4,
      "time": "2155-04-27 20:19:15",
      "speaker": "Patient",
      "text": "Yes, it was normal. No diarrhea or constipation. But I’m really worried—could this be pancreatitis again?"
    },
    {
      "turn_number": 5,
      "time": "2155-04-27 20:21:00",
      "speaker": "Doctor",
      "text": "That’s a possibility, given your history. But your lab work shows your amylase is 99—within normal range—and no signs of infection. Your symptoms suggest your sphincter of Oddi might be spasming again."
    },
    {
      "turn_number": 6,
      "time": "2155-04-27 20:22:30",
      "speaker": "Patient",
      "text": "So not pancreatitis this time? But it feels just like before."
    },
    {
      "turn_number": 7,
      "time": "2155-04-27 20:24:00",
      "speaker": "Doctor",
      "text": "It can feel very similar. But since your enzyme levels are stable and you’ve had recurrent issues, we’ve scheduled an ERCP tomorrow morning to check the bile duct and possibly dilate the ampulla to help with drainage."
    },
    {
      "turn_number": 8,
      "time": "2155-04-27 20:25:30",
      "speaker": "Patient",
      "text": "I had that before. Is it safe to do it again?"
    },
    {
      "turn_number": 9,
      "time": "2155-04-27 20:27:00",
      "speaker": "Doctor",
      "text": "Yes, it’s routine. You already have a sphincterotomy from before, so we’ll use a balloon to gently widen the opening again. No stones were seen on imaging, so we don’t expect complications."
    },
    {
      "turn_number": 10,
      "time": "2155-04-27 20:28:30",
      "speaker": "Patient",
      "text": "Okay, that makes sense. Will I be asleep during it?"
    },
    {
      "turn_number": 11,
      "time": "2155-04-27 20:29:45",
      "speaker": "Doctor",
      "text": "You’ll be under sedation, so you’ll be very relaxed and won’t feel anything. The procedure takes about 30 to 45 minutes."
    },
    {
      "turn_number": 12,
      "time": "2155-04-28 12:30:00",
      "speaker": "Doctor",
      "text": "Hi again. The ERCP is done. We dilated the ampulla successfully, and bile flow improved right away. No stones or blockages were found. The ducts look clear."
    },
    {
      "turn_number": 13,
      "time": "2155-04-28 12:32:00",
      "speaker": "Patient",
      "text": "That’s good news. Does that mean the pain should go away?"
    },
    {
      "turn_number": 14,
      "time": "2155-04-28 12:34:00",
      "speaker": "Doctor",
      "text": "We expect it to improve. You’re already saying you feel better, and you haven’t had nausea since the procedure. We’ll start you on clear liquids and see how you do."
    },
    {
      "turn_number": 15,
      "time": "2155-04-28 14:00:00",
      "speaker": "Doctor",
      "text": "You’ve tolerated the clear diet well, so we’re upgrading you to a regular diet. Your vitals are stable, and your abdomen is soft and not tender."
    },
    {
      "turn_number": 16,
      "time": "2155-04-28 14:02:00",
      "speaker": "Patient",
      "text": "That’s great. When can I go home?"
    },
    {
      "turn_number": 17,
      "time": "2155-04-28 14:04:00",
      "speaker": "Doctor",
      "text": "Later today, likely within the next few hours. We’ll make sure you can eat without pain and give you updated prescriptions, including a stool softener to prevent constipation."
    },
    {
      "turn_number": 18,
      "time": "2155-04-28 15:30:00",
      "speaker": "Doctor",
      "text": "All set. Your discharge instructions are ready. No changes to your usual medications except adding docusate and senna. Keep taking your hydrocodone only if needed for pain."
    },
    {
      "turn_number": 19,
      "time": "2155-04-28 15:32:00",
      "speaker": "Patient",
      "text": "And I still need to follow up with my GI doctor?"
    },
    {
      "turn_number": 20,
      "time": "2155-04-28 15:34:00",
      "speaker": "Doctor",
      "text": "Yes, same plan—follow up with Dr. ___ in one week. They’ll decide if you need another procedure later. In the meantime, call if pain worsens or you can’t keep food down."
    },
    {
      "turn_number": 21,
      "time": "2155-04-28 15:36:00",
      "speaker": "Patient",
      "text": "Thank you. I feel much better already. I’m glad we did this."
    },
    {
      "turn_number": 22,
      "time": "2155-04-28 15:38:00",
      "speaker": "Doctor",
      "text": "Glad to hear it. You’re doing well. We’ll have you out of here soon. Rest at home and take it easy for the next day or two."
    },
    {
      "turn_number": 23,
      "time": "2155-04-28 16:00:00",
      "speaker": "Doctor",
      "text": "Just a quick check-in before discharge. Any new pain or nausea?"
    },
    {
      "turn_number": 24,
      "time": "2155-04-28 16:01:30",
      "speaker": "Patient",
      "text": "No, still feeling okay. A little tired, but the pain is much less."
    },
    {
      "turn_number": 25,
      "time": "2155-04-28 16:03:00",
      "speaker": "Doctor",
      "text": "That’s expected. The sedation can linger a bit. Keep someone with you tonight, and don’t drive until tomorrow."
    },
    {
      "turn_number": 26,
      "time": "2155-04-28 16:30:00",
      "speaker": "Doctor",
      "text": "Your discharge papers are signed. You’re cleared to go home now. Take care, and follow up as planned."
    },
    {
      "turn_number": 27,
      "time": "2155-04-28 16:31:30",
      "speaker": "Patient",
      "text": "Thank you, Dr. Lee. I appreciate everything."
    },
    {
      "turn_number": 28,
      "time": "2155-04-28 16:33:00",
      "speaker": "Doctor",
      "text": "You’re welcome. Feel better soon."
    }
  ],
  "summary": {
    "admission_start": "2155-04-27 20:00:00",
    "admission_end": "2155-04-28 17:50:00",
    "summary_paragraph": "A woman with a history of chronic abdominal pain due to suspected sphincter of Oddi dysfunction was readmitted due to worsening pain and nausea after a recent discharge. She underwent an ERCP with ampullary dilation, which showed no stones or blockages and improved bile flow. Post-procedure, she reported reduced pain, tolerated a diet advancement, and remained stable. She was discharged home the following day with no changes to her home medications except the addition of a stool softener and stimulant laxative. Follow-up with her GI specialist was planned for one week later.",
    "problems": [
      "Abdominal pain, unspecified site",
      "Other specified disorders of biliary tract",
      "Other nonspecific abnormal serum enzyme levels",
      "Constipation, unspecified",
      "Anxiety state, unspecified",
      "Depressive disorder, not elsewhere classified",
      "Posttraumatic stress disorder",
      "Unspecified hearing loss",
      "Need for prophylactic vaccination and inoculation against diphtheria-tetanus-pertussis, combined [DTP] [DTaP]"
    ]
  }
}
